(2082028, 285152, 31885, '<td valign="top">Great colours and nice capture.</td>', 'Great colours and nice capture.', '2006-01-25 09:30:36.000000', NULL, 1),
(2082032, 283982, 34134, '<td valign="top">Really nice lighting. Good capture.</td>', 'Really nice lighting. Good capture.', '2006-01-25 09:32:04.000000', NULL, 1),
(2082037, 285333, 31885, '<td valign="top">I like this a lot - the shadow is brilliant!</td>', 'I like this a lot - the shadow is brilliant!', '2006-01-25 09:33:16.000000', NULL, 1),
(2082040, 285016, 34134, '<td valign="top">I like the overall composition. Nice tone and color. Would be much more effective if the bird not dead center. Well exposed. Still a high score from me.</td>', 'I like the overall composition. Nice tone and color. Would be much more effective if the bird not dead center. Well exposed. Still a high score from me.', '2006-01-25 09:34:19.000000', NULL, 1),
