(2082097, 285600, 31885, '<td valign="top">Good composition, nice detail. Could use some dodge and burn on the beak.</td>', 'Good composition, nice detail. Could use some dodge and burn on the beak.', '2006-01-25 09:49:13.000000', NULL, 1),
(2082100, 285414, 41521, '<td valign="top">Nice horses, but they are domestic creatures, and enclosed in a fence.</td>', 'Nice horses, but they are domestic creatures, and enclosed in a fence.', '2006-01-25 09:50:55.000000', NULL, 1),
(2082105, 284231, 31885, '<td valign="top">This is a spectacular image!!! The composition, lighting, everything is perfect! I even like the background. 10</td>', 'This is a spectacular image!!! The composition, lighting, everything is perfect! I even like the background. 10', '2006-01-25 09:51:46.000000', NULL, 1),
(2082106, 284343, 41521, '<td valign="top">Great capture, cute little bird</td>', 'Great capture, cute little bird', '2006-01-25 09:51:54.000000', NULL, 1),
(2082111, 284542, 31885, '<td valign="top">The focus is not quite right.</td>', 'The focus is not quite right.', '2006-01-25 09:53:29.000000', NULL, 1),
(2082112, 284802, 41521, '<td valign="top">Nice shot, but i''d like more light (backfill?) to bring out the details in his face.  Also, peacocks are domestic fowl, and not wildlife.</td>', 'Nice shot, but i''d like more light (backfill?) to bring out the details in his face.  Also, peacocks are domestic fowl, and not wildlife.', '2006-01-25 09:53:47.000000', NULL, 1),
(2082113, 284703, 3102, '<td valign="top">The first shot in this challenge that has inspired me to say, "WOW!"  Excellent work!!  - 10</td>', 'The first shot in this challenge that has inspired me to say, "WOW!"  Excellent work!!  - 10', '2006-01-25 09:53:53.000000', NULL, 1),
