INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2084039, 284439, 46020, '<td valign="top">I hope you have the lens you used listed in the comments section.  This is absolutly beautiful.</td>', 'I hope you have the lens you used listed in the comments section.  This is absolutly beautiful.', '2006-01-25 17:46:12.000000', NULL, 1),
(2084041, 285361, 51988, '<td valign="top">Good contrasting color. Very vibrant!</td>', 'Good contrasting color. Very vibrant!', '2006-01-25 17:46:31.000000', NULL, 1),
(2084042, 284517, 34659, '<td valign="top">I don''t know if this is actually in the wild or not - but it''s such a magnificent shot - WOW!  Perfect focus &amp; lighting.  Love the rich natural color tones.  Have to give you the benefit of the doubt regarding natural environment.  10</td>', 'I don''t know if this is actually in the wild or not - but it''s such a magnificent shot - WOW!  Perfect focus & lighting.  Love the rich natural color tones.  Have to give you the benefit of the doubt regarding natural environment.  10', '2006-01-25 17:46:38.000000', NULL, 1),
(2084046, 285316, 38869, '<td valign="top">Tough shot to take!</td>', 'Tough shot to take!', '2006-01-25 17:47:05.000000', NULL, 1),
(2084048, 285742, 51988, '<td valign="top">Nice detail!</td>', 'Nice detail!', '2006-01-25 17:47:35.000000', NULL, 1),
(2084052, 285316, 34659, '<td valign="top">It doesn''t get much better than this...  Stunningly beautiful capture.  Tack sharp, great DOF, nice natural color tones, good lighting control, pleasing composition, what else is there?  :-)  Great job!  10</td>', 'It doesn''t get much better than this...  Stunningly beautiful capture.  Tack sharp, great DOF, nice natural color tones, good lighting control, pleasing composition, what else is there?  :-)  Great job!  10', '2006-01-25 17:49:19.000000', NULL, 1),
(2084056, 285152, 51988, '<td valign="top">Nice Capture!</td>', 'Nice Capture!', '2006-01-25 17:49:42.000000', NULL, 1),
(2084058, 283218, 51988, '<td valign="top">Not quite sure what the subject is, sorry.</td>', 'Not quite sure what the subject is, sorry.', '2006-01-25 17:51:19.000000', NULL, 1),
(2084063, 284682, 19936, '<td valign="top">This one gets points for degree of difficulty.  Nice catch.  I know exposure and focus are tough on these.</td>', 'This one gets points for degree of difficulty.  Nice catch.  I know exposure and focus are tough on these.', '2006-01-25 17:52:11.000000', NULL, 1),
(2084066, 284143, 51988, '<td valign="top">This would have been a good one for the romance challenge too. Nice pic.</td>', 'This would have been a good one for the romance challenge too. Nice pic.', '2006-01-25 17:53:09.000000', NULL, 1),
