(2084673, 284697, 49961, '<td valign="top">Wow!</td>', 'Wow!', '2006-01-25 20:36:12.000000', NULL, 1),
(2084674, 285745, 49447, '<td valign="top">Photo is very sharp, I thought the colors were a little over saturated so I looked up the Anna''s.  I still think so, but I like the photo overall.</td>', 'Photo is very sharp, I thought the colors were a little over saturated so I looked up the Anna''s.  I still think so, but I like the photo overall.', '2006-01-25 20:36:47.000000', NULL, 1),
