(2084712, 285380, 3569, '<td valign="top">a little fuzzy but a great capture</td>', 'a little fuzzy but a great capture', '2006-01-25 20:52:01.000000', NULL, 1),
(2084714, 285522, 43019, '<td valign="top">I wish the photograph was bigger to see more detail, but I love the idea of your photo- good job! That seems very unexpected to see a deer in a cemetary...</td>', 'I wish the photograph was bigger to see more detail, but I love the idea of your photo- good job! That seems very unexpected to see a deer in a cemetary...', '2006-01-25 20:52:17.000000', NULL, 1),
