(2091725, 284420, 43774, '<td valign="top">Beautiful shot, 9 from me.</td>', 'Beautiful shot, 9 from me.', '2006-01-27 10:05:33.000000', NULL, 1),
(2091727, 284981, 15711, '<td valign="top">AWWW. Maybe have the focus on the bird, as it''s the wild life - with the blur on the kitty??</td>', 'AWWW. Maybe have the focus on the bird, as it''s the wild life - with the blur on the kitty??', '2006-01-27 10:05:43.000000', NULL, 1),
