(2091751, 283301, 43774, '<td valign="top">Great capture, a little too squarely cropped and a little too centered for my tastes though.</td>', 'Great capture, a little too squarely cropped and a little too centered for my tastes though.', '2006-01-27 10:09:32.000000', NULL, 1),
(2091752, 285531, 43774, '<td valign="top">Beautiful capture, 8</td>', 'Beautiful capture, 8', '2006-01-27 10:09:43.000000', NULL, 1),
