(2093631, 283301, 15711, '<td valign="top">Tack sharp focus. Love the outstretched legs.  Well done.</td>', 'Tack sharp focus. Love the outstretched legs.  Well done.', '2006-01-27 22:18:02.000000', NULL, 1),
(2093707, 284617, 75713, '<td valign="top">Nice light in the eye, the feathers are crisp and the water has some interesting patterns and hues - good job</td>', 'Nice light in the eye, the feathers are crisp and the water has some interesting patterns and hues - good job', '2006-01-27 22:42:58.000000', NULL, 1),
