(2093811, 285600, 1280, '<td valign="top">Nice, with good colour. Beak is a little oe. Dof is good.</td>', 'Nice, with good colour. Beak is a little oe. Dof is good.', '2006-01-27 23:05:52.000000', NULL, 1),
(2093813, 284136, 44242, '<td valign="top">very striking photograph. great sharpness and good lighting. slightly dark.</td>', 'very striking photograph. great sharpness and good lighting. slightly dark.', '2006-01-27 23:06:34.000000', NULL, 1),
