(2094811, 285687, 30982, '<td valign="top">Good title.</td>', 'Good title.', '2006-01-28 08:57:19.000000', NULL, 1),
(2094814, 285326, 30982, '<td valign="top">Lovely color work and nice lines with the way you shot down the line of bouganvilla.</td>', 'Lovely color work and nice lines with the way you shot down the line of bouganvilla.', '2006-01-28 08:58:12.000000', NULL, 1),
