INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2103439, 284646, 34539, '<td valign="top">Wonderful action shot. (8) Hopefully this isn''t a zoo shot.</td>', 'Wonderful action shot. (8) Hopefully this isn''t a zoo shot.', '2006-01-30 19:49:32.000000', NULL, 1),
